"""Stable Unity folder and PNG import metadata; GLB metadata is generated by Unity/glTFast."""
from pathlib import Path
import uuid
root=Path(__file__).resolve().parent.parent
namespace=uuid.UUID('a542c69b-f8e7-4d6e-a9d9-d3c9a9c59b71')
model_root=root/'Assets/Models'
for folder in [model_root,*sorted(p for p in model_root.rglob('*') if p.is_dir())]:
    meta=Path(str(folder)+'.meta')
    if not meta.exists():
        guid=uuid.uuid5(namespace,folder.relative_to(root).as_posix()).hex
        meta.write_text(f'fileFormatVersion: 2\nguid: {guid}\nfolderAsset: yes\nDefaultImporter:\n  externalObjects: {{}}\n  userData: \n  assetBundleName: \n  assetBundleVariant: \n')
for file in model_root.rglob('*.png'):
    meta=Path(str(file)+'.meta')
    if meta.exists():continue
    guid=uuid.uuid5(namespace,file.relative_to(root).as_posix()).hex
    normal='_normal' in file.stem;linear=normal or '_roughness' in file.stem
    alpha='spawn-circle' in file.stem
    meta.write_text(f'''fileFormatVersion: 2
guid: {guid}
TextureImporter:
  internalIDToNameTable: []
  externalObjects: {{}}
  serializedVersion: 13
  mipmaps:
    mipMapMode: 0
    enableMipMap: 1
    sRGBTexture: {0 if linear else 1}
  isReadable: 0
  streamingMipmaps: 0
  maxTextureSize: 2048
  textureSettings:
    serializedVersion: 2
    filterMode: 1
    aniso: 4
    mipBias: 0
    wrapU: {1 if alpha else 0}
    wrapV: {1 if alpha else 0}
    wrapW: 0
  textureFormat: 1
  textureCompression: 1
  compressionQuality: 50
  alphaSource: 1
  alphaIsTransparency: {1 if alpha else 0}
  textureType: {1 if normal else 0}
  textureShape: 1
  convertToNormalMap: 0
  userData:
  assetBundleName:
  assetBundleVariant:
''')
for meta in [Path(str(model_root)+'.meta'),*model_root.rglob('*.meta')]:
    meta.write_text('\n'.join(line.rstrip() for line in meta.read_text().splitlines())+'\n')
print('Stable folder and PNG metadata written.')
